    int querySkuDetails(String itemType, Inventory inv, List<String> moreSkus) throws RemoteException, JSONException {
        IABConstants.logDebug("Querying SKU details.");
        ArrayList<String> skuList = new ArrayList<>();
        skuList.addAll(inv.getAllOwnedSkus());
        if (moreSkus != null) {
            for (String sku : moreSkus) {
                if (!skuList.contains(sku)) {
                    skuList.add(sku);
                }
            }
        }
        if (skuList.size() == 0) {
            IABConstants.logDebug("queryPrices: nothing to do because there are no SKUs.");
            return 0;
        }
        ArrayList<ArrayList<String>> packs = new ArrayList<>();
        int n = skuList.size() / 20;
        int mod = skuList.size() % 20;
        for (int i = 0; i < n; i++) {
            ArrayList<String> tempList = new ArrayList<>();
            for (String s : skuList.subList(i * 20, (i * 20) + 20)) {
                tempList.add(s);
            }
            packs.add(tempList);
        }
        if (mod != 0) {
            ArrayList<String> tempList2 = new ArrayList<>();
            for (String s2 : skuList.subList(n * 20, (n * 20) + mod)) {
                tempList2.add(s2);
            }
            packs.add(tempList2);
        }
        Iterator<ArrayList<String>> it = packs.iterator();
        while (it.hasNext()) {
            ArrayList<String> skuPartList = it.next();
            Bundle querySkus = new Bundle();
            querySkus.putStringArrayList(GET_SKU_DETAILS_ITEM_LIST, skuPartList);
            Bundle skuDetails = this._service.getSkuDetails(3, this._context.getPackageName(), itemType, querySkus);
            if (!skuDetails.containsKey(RESPONSE_GET_SKU_DETAILS_LIST)) {
                int response = getResponseCodeFromBundle(skuDetails);
                if (response != 0) {
                    Log.i(TAG, "getSkuDetails() failed: " + getResponseDesc(response));
                    return response;
                }
                logError("getSkuDetails() returned a bundle with neither an error nor a detail list.");
                return IABHELPER_BAD_RESPONSE;
            }
            ArrayList<String> responseList = skuDetails.getStringArrayList(RESPONSE_GET_SKU_DETAILS_LIST);
            Iterator<String> it2 = responseList.iterator();
            while (it2.hasNext()) {
                String thisResponse = it2.next();
                SkuDetails d = new SkuDetails(itemType, thisResponse);
                IABConstants.logDebug("Got sku details: " + d);
                inv.addSkuDetails(d);
            }
        }
        return 0;
    }

